#include <stdio.h>

int main() {
    // if-else 分支结构
    int score = 85;
    if (score >= 90) {
        printf("优秀\n");
    } else if (score >= 60) {
        printf("及格\n");
    } else {
        printf("不及格\n");
    }

    // for 循环结构
    for (int i = 0; i < 5; i++) {
        if (i == 3) break;  // 跳出循环
        printf("%d ", i);
    }

    return 0;
}
